import type { User, UserRole } from '@/modules/shared/types/user';

type MockUserRoleName = 'admin' | 'leadership' | 'pm' | 'superintendent' | 'viewer';

interface MockUserRecord extends Omit<User, 'role' | 'job_title' | 'last_login_at' | 'role_version'> {
  role: MockUserRoleName;
  job_title?: string | null;
}

function createMockRole(name: MockUserRoleName): UserRole {
  return {
    id: name,
    name,
    isSystem: true,
  };
}

